    73	export interface RunInstanceOptions {
    74	  imageId: string;
    75	  instanceType: string;
    76	  /** Base64-encoded cloud-init user_data. */
    77	  userData: string;
    78	  name?: string;
    79	  securityGroupId?: string;
    80	  subnetId?: string;
    81	  keyName?: string;
    82	}
    83	
    84	export async function runInstance(
    85	  c: Ec2Client,
    86	  opts: RunInstanceOptions
    87	): Promise<{ instanceId: string }> {
    88	  const params: Record<string, string> = {
    89	    Action: 'RunInstances',
    90	    ImageId: opts.imageId,
    91	    InstanceType: opts.instanceType,
    92	    MinCount: '1',
    93	    MaxCount: '1',
    94	    UserData: opts.userData,
    95	    // Tag at creation so the IAM aws:RequestTag condition is satisfied.
    96	    'TagSpecification.1.ResourceType': 'instance',
    97	    'TagSpecification.1.Tag.1.Key': MANAGED_BY_TAG_KEY,
    98	    'TagSpecification.1.Tag.1.Value': MANAGED_BY_TAG_VALUE,
    99	  };
   100	  if (opts.name) {
   101	    params['TagSpecification.1.Tag.2.Key'] = 'Name';
   102	    params['TagSpecification.1.Tag.2.Value'] = opts.name;
   103	  }
   104	  if (opts.securityGroupId) params['SecurityGroupId.1'] = opts.securityGroupId;
   105	  if (opts.subnetId) params['SubnetId'] = opts.subnetId;
   106	  if (opts.keyName) params['KeyName'] = opts.keyName;
   107	
   108	  const xml = await ec2Call(c, params);
   109	  const instanceId = extract(xml, 'instanceId');
   110	  if (!instanceId) throw new Error('RunInstances returned no instanceId');
   111	  return { instanceId };
   112	}
