   144	export type InstanceLifecycle =
   145	  | 'pending'
   146	  | 'running'
   147	  | 'shutting-down'
   148	  | 'terminated'
   149	  | 'stopping'
   150	  | 'stopped'
   151	  | 'unknown';
   152	
   153	export interface InstanceStatus {
   154	  instanceId: string;
   155	  state: InstanceLifecycle;
   156	  publicIp?: string;
   157	  publicDns?: string;
   158	}
   159	
   160	export async function describeInstance(c: Ec2Client, instanceId: string): Promise<InstanceStatus> {
   161	  const xml = await ec2Call(c, { Action: 'DescribeInstances', 'InstanceId.1': instanceId });
   162	  // Scope to <instanceState> so a stray <name> elsewhere can't be picked up.
   163	  const stateMatch = xml.match(/<instanceState>[\s\S]*?<name>([^<]+)<\/name>/);
   164	  const state = (stateMatch ? (stateMatch[1] as InstanceLifecycle) : 'unknown');
   165	  const publicIp = extract(xml, 'ipAddress');
   166	  const publicDns = extract(xml, 'dnsName');
   167	  return {
   168	    instanceId,
   169	    state,
   170	    publicIp: publicIp || undefined,
   171	    publicDns: publicDns || undefined,
   172	  };
   173	}
